/* Advanced Raytracing Shader with Multiple Objects and Complex Lighting */

#define MAX_STEPS 100
#define MAX_DIST 100.0
#define SURF_DIST 0.001
#define SHADOW_SOFTNESS 32.0
#define MAX_LIGHTS 3

// Material IDs
#define MAT_DIFFUSE 1
#define MAT_MIRROR 2
#define MAT_METALLIC 3
#define MAT_EMISSIVE 4

// Light structure
struct Light {
    vec3 position;
    vec3 color;
    float intensity;
};

// Material structure
struct Material {
    vec3 albedo;
    float metallic;
    float roughness;
    float emissive;
    vec3 emissiveColor;
};

// Scene objects SDFs
float sdfSphere1(vec3 p) {
    return length(p - vec3(0.0, 0.0, 3.0)) - 1.0;
}

float sdfMetallicSphere(vec3 p) {
    return length(p - vec3(2.0, 0.0, 3.0)) - 0.7;
}

float sdfMirrorPlane(vec3 p) {
    return p.y + 1.0;
}

float sdfEmissiveCube(vec3 p) {
    vec3 cubePos = vec3(-1.5, -0.5, 2.0);
    vec3 d = abs(p - cubePos) - vec3(0.3);
    return length(max(d, 0.0)) + min(max(d.x, max(d.y, d.z)), 0.0);
}

// Combined scene SDF
float sdfScene(vec3 p) {
    float d1 = sdfSphere1(p);
    float d2 = sdfMirrorPlane(p);
    float d3 = sdfMetallicSphere(p);
    float d4 = sdfEmissiveCube(p);
    return min(min(min(d1, d2), d3), d4);
}

// Get material properties for a point
Material getMaterial(vec3 p) {
    float d1 = sdfSphere1(p);
    float d2 = sdfMirrorPlane(p);
    float d3 = sdfMetallicSphere(p);
    float d4 = sdfEmissiveCube(p);

    Material mat;
    float minDist = min(min(min(d1, d2), d3), d4);

    if (minDist == d1) {
        // Red diffuse sphere
        mat.albedo = vec3(0.9, 0.2, 0.2);
        mat.metallic = 0.0;
        mat.roughness = 0.7;
        mat.emissive = 0.0;
        mat.emissiveColor = vec3(0.0);
    } else if (minDist == d2) {
        // Mirror plane
        mat.albedo = vec3(0.8);
        mat.metallic = 1.0;
        mat.roughness = 0.1;
        mat.emissive = 0.0;
        mat.emissiveColor = vec3(0.0);
    } else if (minDist == d3) {
        // Metallic sphere
        mat.albedo = vec3(0.95, 0.64, 0.54); // Copper color
        mat.metallic = 1.0;
        mat.roughness = 0.2;
        mat.emissive = 0.0;
        mat.emissiveColor = vec3(0.0);
    } else {
        // Emissive cube
        mat.albedo = vec3(1.0);
        mat.metallic = 0.0;
        mat.roughness = 1.0;
        mat.emissive = 1.0;
        mat.emissiveColor = vec3(0.3, 0.8, 1.0) * 5.0; // Bright blue
    }

    return mat;
}

// Fresnel-Schlick approximation
vec3 fresnelSchlick(float cosTheta, vec3 F0) {
    return F0 + (1.0 - F0) * pow(clamp(1.0 - cosTheta, 0.0, 1.0), 5.0);
}

float raymarch(vec3 ro, vec3 rd) {
    float dO = 0.0;
    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * dO;
        float dS = sdfScene(p);
        if (dS < SURF_DIST) return dO;
        dO += dS;
        if (dO > MAX_DIST) break;
    }
    return MAX_DIST;
}

vec3 getNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    float d = sdfScene(p);
    vec3 n = d - vec3(
        sdfScene(p - e.xyy),
        sdfScene(p - e.yxy),
        sdfScene(p - e.yyx)
    );
    return normalize(n);
}

float softShadow(vec3 ro, vec3 rd, float mint, float maxt, float k) {
    float res = 1.0;
    float ph = 1e20;
    float t = mint;
    for(int i = 0; i < 32; i++) {
        float h = sdfScene(ro + rd * t);
        if(h < 0.001) return 0.0;
        float y = h * h / (2.0 * ph);
        float d = sqrt(h * h - y * y);
        res = min(res, k * d / max(0.0, t - y));
        ph = h;
        t += h;
        if(t > maxt) break;
    }
    return res;
}

float calcAO(vec3 p, vec3 n) {
    float occ = 0.0;
    float sca = 1.0;
    for(int i = 0; i < 5; i++) {
        float h = 0.01 + 0.12 * float(i) / 4.0;
        float d = sdfScene(p + h * n);
        occ += (h - d) * sca;
        sca *= 0.95;
    }
    return clamp(1.0 - 3.0 * occ, 0.0, 1.0);
}

// Calculate light contribution from all sources
vec3 calculateLighting(vec3 p, vec3 normal, vec3 viewDir, Material mat, Light lights[MAX_LIGHTS]) {
    vec3 totalLight = vec3(0.0);
    vec3 F0 = mix(vec3(0.04), mat.albedo, mat.metallic);

    // Add emissive contribution
    if (mat.emissive > 0.0) {
        return mat.emissiveColor;
    }

    // Ambient light
    vec3 ambient = vec3(0.03) * mat.albedo;

    // Process each light
    for (int i = 0; i < MAX_LIGHTS; i++) {
        vec3 lightDir = normalize(lights[i].position - p);
        float distance = length(lights[i].position - p);
        float attenuation = 1.0 / (1.0 + 0.09 * distance + 0.032 * distance * distance);

        // Shadow calculation
        float shadow = softShadow(p + normal * SURF_DIST * 2.0, lightDir, 0.02, distance, SHADOW_SOFTNESS);

        // Fresnel
        vec3 halfwayDir = normalize(lightDir + viewDir);
        vec3 F = fresnelSchlick(max(dot(halfwayDir, viewDir), 0.0), F0);

        // Diffuse
        vec3 diffuse = (1.0 - F) * (1.0 - mat.metallic) * mat.albedo / 3.14159;

        // Specular
        float NdotH = max(dot(normal, halfwayDir), 0.0);
        float spec = pow(NdotH, (1.0 - mat.roughness) * 256.0);
        vec3 specular = F * spec * mat.metallic;

        // Combine components
        float NdotL = max(dot(normal, lightDir), 0.0);
        vec3 radiance = lights[i].color * lights[i].intensity * attenuation;
        totalLight += (diffuse + specular) * radiance * NdotL * shadow;
    }

    return ambient + totalLight;
}

// Analytical ray-plane intersection
float intersectPlane(vec3 ro, vec3 rd, vec3 planeNormal, float planeHeight) {
    float denom = dot(rd, planeNormal);
    if (abs(denom) < 1e-6) return MAX_DIST;
    float t = -(dot(ro, planeNormal) + planeHeight) / denom;
    return t > 0.0 ? t : MAX_DIST;
}

vec3 trace(vec3 ro, vec3 rd) {
    vec3 color = vec3(0.0);
    float attenuation = 1.0;
    const int MAX_BOUNCES = 4;

    // Setup lights
    Light lights[MAX_LIGHTS];
    lights[0] = Light(vec3(2.0, 4.0, -3.0), vec3(1.0, 0.9, 0.8), 10.0);    // Main light
    lights[1] = Light(vec3(-1.5, -0.5, 2.0), vec3(0.3, 0.8, 1.0), 5.0);    // Emissive cube
    lights[2] = Light(vec3(-2.0, 3.0, 0.0), vec3(1.0, 0.6, 0.3), 8.0);     // Fill light

    for (int bounce = 0; bounce < MAX_BOUNCES; bounce++) {
        // Check for plane intersection first
        float planeT = intersectPlane(ro, rd, vec3(0.0, 1.0, 0.0), 1.0);
        float d = raymarch(ro, rd);

        // Use plane intersection if it's closer than other objects
        bool hitPlane = planeT < d && planeT < MAX_DIST - 0.001;
        float hitDist = hitPlane ? planeT : d;

        if (hitDist > MAX_DIST - 0.001) {
            // Sky color
            color += attenuation * vec3(0.2, 0.3, 0.5) * 0.2;
            break;
        }

        vec3 p = ro + rd * hitDist;
        vec3 normal = hitPlane ? vec3(0.0, 1.0, 0.0) : getNormal(p);
        Material mat = getMaterial(p);

        // Calculate lighting
        vec3 lighting = calculateLighting(p, normal, -rd, mat, lights);

        // Add lighting contribution
        color += attenuation * lighting;

        // Handle reflections based on material properties
        float fresnel = length(fresnelSchlick(max(dot(normal, -rd), 0.0), vec3(0.04)));
        float reflectivity = mix(fresnel, 1.0, mat.metallic);

        if (reflectivity > 0.001) {
            rd = reflect(rd, normal);
            ro = p + normal * SURF_DIST * 2.0;
            attenuation *= reflectivity * (1.0 - mat.roughness);
            continue;
        }

        break;
    }

    return color;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec3 ro = vec3(0.0, 1.0, -5.0);
    vec3 rd = normalize(vec3(uv, 2.0));

    vec3 col = trace(ro, rd);

    // Tone mapping
    col = col / (col + vec3(1.0));

    // Gamma correction (using standard 2.2 gamma)
    col = pow(col, vec3(1.0/2.2));

    fragColor = vec4(col, 1.0);
}
